keyframes.text:
@keyframes float {
    0% {
      transform: none;
    }

    50% {
      transform: translateY(-1.25rem);
    }

    to {
      transform: none;
    }
  }

@keyframes heart {
    0% {
      transform: scale(1);
    }

    14% {
      transform: scale(1.3);
    }

    28% {
      transform: scale(1);
    }

    42% {
      transform: scale(1.3);
    }

    70% {
      transform: scale(1);
    }
  }

@keyframes jump {
    0%, to {
      transform: translateY(-25%);
      animation-timing-function: cubic-bezier(.8, 0, 1, 1);
    }

    50% {
      transform: translateY(0);
      animation-timing-function: cubic-bezier(0, 0, .2, 1);
    }
  }

@keyframes pulse {
    0% {
      transform: none;
    }

    50% {
      transform: scale(1.05);
    }

    to {
      transform: none;
    }
  }

@keyframes rotate {
    0% {
      transform: rotate(-360deg);
    }

    to {
      transform: none;
    }
  }

@keyframes shake {
    0% {
      transform: none;
    }

    6.5% {
      transform: translateX(-6px) rotateY(-9deg);
    }

    18.5% {
      transform: translateX(5px) rotateY(7deg);
    }

    31.5% {
      transform: translateX(-3px) rotateY(-5deg);
    }

    43.5% {
      transform: translateX(2px) rotateY(3deg);
    }

    50% {
      transform: none;
    }
  }

@keyframes zoom {
    0% {
      transform: scale(0);
    }

    to {
      transform: none;
    }
  }
